<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useTicketsStore} from '@/stores/tickets'
import {useTicketService} from '@/services/ticket.service'
import BaseCard from '@/components/common/BaseCard.vue'
import BaseButton from '@/components/common/BaseButton.vue'
import {technicianService} from '@/services/technician.service'
import {parseDateOnly,toDateOnly} from '@/utils/dates'
import type {TicketStatus,TicketPriority,Ticket,User} from '@/types'
const props=defineProps<{ticketId?:string}>(),emit=defineEmits<{(e:'saved'):void;(e:'cancel'):void}>()
const ticketsStore=useTicketsStore(),{getBuildings}=useTicketService(),formData=ref({title:'',description:'',buildingId:null as number|null,buildingName:'',technicianName:'',assignedTo:null as string|null,attentionDate:null as Date|null,recommendations:'',observations:'',priority:'medium' as TicketPriority,status:'pending' as TicketStatus}),buildings=ref<any[]>([]),technicians=ref<User[]>([]),initialAssignedTo=ref<string|null>(null),errors=ref<Record<string,string>>({}),loading=ref(false),isEdit=ref(false)
const priorityOptions=[{label:'Baja',value:'low'},{label:'Media',value:'medium'},{label:'Alta',value:'high'},{label:'Urgente',value:'urgent'}],statusOptions=[{label:'Pendiente',value:'pending'},{label:'En progreso',value:'in_progress'},{label:'Resuelto',value:'resolved'},{label:'Cerrado',value:'closed'},{label:'Cancelado',value:'cancelled'}]
async function loadBuildings(){buildings.value=await getBuildings()}
async function loadTechnicians(){technicians.value=await technicianService.list()}
async function loadExistingTicket(){if(!props.ticketId)return;await ticketsStore.loadTicket(props.ticketId);const t=ticketsStore.currentTicket;if(t){formData.value={title:t.title,description:t.description,buildingId:t.buildingId,buildingName:t.buildingName||'',technicianName:t.technicianName||'',assignedTo:t.assignedTo||null,attentionDate:parseDateOnly(t.attentionDate),recommendations:t.recommendations||'',observations:t.observations||'',priority:t.priority,status:t.status};initialAssignedTo.value=t.assignedTo||null;isEdit.value=true}}
function validate(){const e:Record<string,string>={};if(!formData.value.title.trim())e.title='El título es obligatorio';if(!formData.value.description.trim())e.description='La descripción es obligatoria';errors.value=e;return !Object.keys(e).length}
function toPayload():Partial<Ticket>{const payload:Partial<Ticket>={...formData.value,attentionDate:toDateOnly(formData.value.attentionDate),technicianName:formData.value.technicianName||null};const selected=technicians.value.find((technician)=>technician.id===formData.value.assignedTo);if(isEdit.value&&formData.value.assignedTo===initialAssignedTo.value){delete payload.assignedTo;delete payload.technicianName}else{payload.assignedTo=formData.value.assignedTo;payload.technicianName=selected?.fullName||null}return payload}
async function onSubmit(){if(!validate())return;loading.value=true;try{if(isEdit.value&&props.ticketId)await ticketsStore.update(props.ticketId,toPayload());else await ticketsStore.create(toPayload());emit('saved')}finally{loading.value=false}}
onMounted(()=>{loadBuildings();loadTechnicians();if(props.ticketId)loadExistingTicket()})
</script>
<template><BaseCard :title="isEdit?'Editar ticket':'Nuevo ticket'" icon="fa-solid fa-ticket"><form class="form-grid" @submit.prevent="onSubmit">
<div class="form-field form-field--full"><label>Título *</label><InputText v-model="formData.title" class="w-full"/><span v-if="errors.title" class="field-error">{{errors.title}}</span></div><div class="form-field form-field--full"><label>Descripción *</label><Textarea v-model="formData.description" class="w-full" rows="4"/><span v-if="errors.description" class="field-error">{{errors.description}}</span></div>
<div class="form-field"><label>Edificio</label><Dropdown v-model="formData.buildingId" :options="buildings" optionLabel="name" optionValue="id" class="w-full"/></div><div class="form-field"><label>Edificio alternativo</label><InputText v-model="formData.buildingName" class="w-full"/></div><div class="form-field"><label>Técnico asignado</label><Dropdown v-model="formData.assignedTo" :options="technicians" optionLabel="fullName" optionValue="id" filter filterPlaceholder="Buscar técnico" showClear placeholder="Seleccionar técnico" class="w-full"/></div><div class="form-field"><label>Fecha de atención</label><DatePicker v-model="formData.attentionDate" class="w-full" dateFormat="dd/mm/yy" showIcon iconDisplay="input"/></div>
<div class="form-field"><label>Prioridad</label><Dropdown v-model="formData.priority" :options="priorityOptions" optionLabel="label" optionValue="value" class="w-full"/></div><div class="form-field"><label>Estado</label><Dropdown v-model="formData.status" :options="statusOptions" optionLabel="label" optionValue="value" class="w-full"/></div><div class="form-field form-field--full"><label>Recomendaciones</label><Textarea v-model="formData.recommendations" class="w-full" rows="3"/></div><div class="form-field form-field--full"><label>Observaciones</label><Textarea v-model="formData.observations" class="w-full" rows="3"/></div>
<div class="form-actions form-field--full"><BaseButton label="Cancelar" icon="fa-solid fa-xmark" severity="secondary" type="button" @click="emit('cancel')"/><BaseButton :label="loading?'Guardando…':'Guardar ticket'" icon="fa-regular fa-floppy-disk" severity="primary" :loading="loading" type="submit"/></div></form></BaseCard></template>
